import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";

test.describe("Error diagnostic events", () => {
  test.describe.configure({ timeout: 180_000 });

  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Action failure shows error dot and ErrorAlert in details", async ({ inspectorPage }) => {
    await flows.error.triggerActionFailureAndAssertError(inspectorPage);
    await flows.error.openActionFailureDetailsAndAssertError(inspectorPage);
  });

  test("Custom tool failure shows error dot on tool event", async ({ inspectorPage }) => {
    await flows.error.triggerCustomToolFailureAndAssertError(inspectorPage);
    await flows.error.openCustomToolFailureDetailsAndAssertError(inspectorPage);
  });

  test("Direct MCP failure shows MCP error in event details", async ({ inspectorPage }) => {
    await flows.error.triggerDirectMcpFailureAndAssertError(inspectorPage);
    await flows.error.openDirectMcpFailureDetailsAndAssertError(inspectorPage);
  });
});
